"""Structured photography teaching material shared by bot, app and mentor.

Reference photographs illustrate a visible principle; they do not establish the
camera settings, capture method or result of any particular student's work.
All paths are local and reference photos use the existing authenticated API.
"""


def reference(category, index, caption):
    return {"path": f"/academy/practice/references/{category}/{index}",
            "alt": caption, "caption": "Учебный пример. " + caption}


def diagram(name, caption):
    return {"path": f"/app/assets/academy/{name}.svg", "alt": caption, "caption": caption}


def material(objective, explanation, steps, problem, fix, practice, checks,
             references, diagrams=(), minutes=15):
    return {"objective": objective, "explanation": explanation, "steps": list(steps),
            "mistake": {"problem": problem, "fix": fix}, "practice": practice,
            "successChecks": list(checks), "references": list(references),
            "diagrams": list(diagrams), "estimatedMinutes": minutes}


