def lesson_text(slug):
    """Plain text remains useful in existing Telegram and Mini App readers."""
    item = LESSON_MATERIALS[slug]
    return (
        "Цель\n" + item["objective"] + "\n\nРазбор\n" + item["explanation"]
        + "\n\nПорядок действий\n" + "\n".join(f"{i}. {step}" for i, step in enumerate(item["steps"], 1))
        + "\n\nОшибка → исправление\n" + item["mistake"]["problem"] + "\n" + item["mistake"]["fix"]
        + "\n\nПрактика\n" + item["practice"]
        + "\n\nПроверка результата\n" + "\n".join("• " + check for check in item["successChecks"])
    )
